-- Creates 20 Wandering Hearts (Tribal Hearts) seed profiles for browse
-- testing: 10 men seeking women (seed-wh-01..10), 10 women seeking men
-- (seed-wh-11..20). Emails seed-wh-01@sow2grow.test .. seed-wh-20@sow2grow.test.
--
-- Generated by this session -- NOT executed automatically. Creating 20 real
-- auth.users rows in one shot was blocked by the sandbox's safety
-- classifier (a bulk write to the auth system is exactly the kind of
-- consequential action that should get a human's eyes first), so this is
-- handed off as a script instead of applied directly.
--
-- What each block does, per person:
--   1. INSERT INTO auth.users -- a real account. Password is a bcrypt hash
--      of a random UUID that is generated and discarded in the same
--      expression (crypt(gen_random_uuid()::text, gen_salt('bf'))) --
--      nobody, including this script, ever knows the plaintext, so the
--      account is genuinely unusable to log into. Requires pgcrypto
--      (already enabled on this project).
--   2. INSERT INTO auth.identities -- the matching email/password identity
--      GoTrue expects alongside the auth.users row.
--   3. UPDATE public.profiles -- the project's own `handle_new_user()`
--      trigger on auth.users fires automatically and creates the base
--      profiles row (first_name/country/location from raw_user_meta_data);
--      this just adds a realistic display_name on top.
--   4. INSERT INTO public.tribal_hearts_profiles -- the actual dating
--      profile: gender, seeking, birthdate (age 25-55), bio, 3-5 interests
--      (from the same INTERESTS list TribalHeartsOnboarding.tsx uses),
--      South African + international cities, is_seed = true.
--   5. INSERT INTO public.s2g_agent_free_access -- grants
--      is_tribal_hearts_member() membership (same table used to grant it
--      to davison -- see spec-payments.md/session notes for why this
--      table rather than fabricating fake ambassador_applications rows:
--      that table represents a real business process, this one is exactly
--      "internal/test access").
--
-- Run in the Supabase SQL editor (Studio) or via the Management API.
-- To undo: scripts/purge-wh-seed.sql.

BEGIN;

INSERT INTO auth.users (
  instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
  raw_app_meta_data, raw_user_meta_data, is_sso_user, is_anonymous, created_at, updated_at,
  confirmation_token, recovery_token, email_change_token_new, email_change,
  email_change_token_current, phone_change, phone_change_token, reauthentication_token
) VALUES (
  '00000000-0000-0000-0000-000000000000', '4101e0f6-2d04-43ce-a7b2-ad800d149086', 'authenticated', 'authenticated',
  'seed-wh-01@sow2grow.test', crypt(gen_random_uuid()::text, gen_salt('bf')), now(),
  '{"provider":"email","providers":["email"]}'::jsonb,
  jsonb_build_object('first_name', 'Thabo', 'country', 'South Africa', 'location', 'Cape Town'),
  false, false, now(), now(), '', '', '', '', '', '', '', ''
);

