  jsonb_build_object('sub', '4101e0f6-2d04-43ce-a7b2-ad800d149086', 'email', 'seed-wh-01@sow2grow.test', 'email_verified', true, 'phone_verified', false),
  'email', now(), now(), now()
);

UPDATE public.profiles SET display_name = 'Thabo Nkosi' WHERE user_id = '4101e0f6-2d04-43ce-a7b2-ad800d149086';

